import os
import tomllib

class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix, env_mapping=os.environ):
    config = defaults.copy()
    if toml_path:
        try:
            with open(toml_path, 'rb') as f:
                toml_config = tomllib.load(f)
                config.update(toml_config)
        except FileNotFoundError:
            pass
    env_config = {}
    for key, value in env_mapping.items():
        if key.startswith(env_prefix):
            env_key = key[len(env_prefix):].replace('__', '.').lower()
            env_config[env_key] = value
    config.update(env_config)
    return config

import pytest
from envcfg import load_config, ConfigError

def test_defaults():
    defaults = {'a': 1, 'b': 'two'}
    config = load_config(defaults)
    assert config == {'a': 1, 'b': 'two'}

def test_toml():
    defaults = {'a': 1, 'b': 'two'}
    config = load_config(defaults, toml_path='config.toml')
    assert config == {'a': 2, 'b': 'two'}

def test_env():
    defaults = {'a': 1, 'b': 'two'}
    env_mapping = {'APP_A': '3', 'APP_B': 'three'}
    config = load_config(defaults, env_prefix='APP_', env_mapping=env_mapping)
    assert config == {'a': 3, 'b': 'three'}

def test_nested_env():
    defaults = {'server': {'port': 8080}}
    env_mapping = {'APP_SERVER_PORT': '8081'}
    config = load_config(defaults, env_prefix='APP_', env_mapping=env_mapping)
    assert config == {'server': {'port': 8081}}

def test_coercion():
    defaults = {'a': 1, 'b': True}
    env_mapping = {'APP_A': '2', 'APP_B': 'false'}
    config = load_config(defaults, env_prefix='APP_', env_mapping=env_mapping)
    assert config == {'a': 2, 'b': False}

def test_missing_toml():
    defaults = {'a': 1}
    config = load_config(defaults, toml_path='missing.toml')
    assert config == {'a': 1}

def test_missing_env():
    defaults = {'a': 1}
    env_mapping = {}
    with pytest.raises(ConfigError):
        load_config(defaults, env_prefix='APP_', env_mapping=env_mapping)

