import os
import tomllib

class ConfigError(Exception):
    pass

def flatten_dict(d, parent_key='', sep='.'):
    items = []
    for k, v in d.items():
        new_key = f'{parent_key}{sep}{k}' if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, sep=sep).items())
        else:
            items.append((new_key, v))
    return dict(items)

def coerce_value(value, default):
    if isinstance(default, int):
        return int(value)
    elif isinstance(default, float):
        return float(value)
    elif isinstance(default, bool):
        return value.lower() in ['true', '1', 'yes']
    elif isinstance(default, str):
        return value
    else:
        raise ConfigError(f'Unsupported type for {value}')

def load_config(defaults, toml_path=None, env_prefix=None, env_mapping=os.environ):
    config = defaults.copy()
    if toml_path:
        try:
            with open(toml_path, 'rb') as f:
                toml_config = tomllib.load(f)
                config.update(flatten_dict(toml_config))
        except FileNotFoundError:
            pass
    env_config = {}
    for key, value in env_mapping.items():
        if env_prefix is not None and key.startswith(env_prefix):
            env_key = key[len(env_prefix):].replace('__', '.').lower()
            env_config[env_key] = coerce_value(value, defaults.get(env_key))
    config.update(env_config)
    return config
